import {
  type ExtensionAPI,
  type ExtensionCommandContext,
  apiFetchJson,
  normalizeKey,
  notify,
  pad,
  truncate,
} from "./shared.js";
import { openSpecDetail } from "./spec-detail.js";

type GenerateSpecRequest = {
  workspaceId: string;
  title: string;
  brief: string;
  storyCount: number;
  model?: string;
};

type GenerateSpecResponse = {
  id?: string;
  title?: string;
  storyCount?: number;
  jobId?: string;
  slug?: string;
  spec?: {
    id?: string;
    title?: string;
  };
};

type GenerateJobResponse = {
  status?: string;
  slug?: string;
  spec?: {
    id?: string;
    title?: string;
  };
  error?: string;
  progress?: number;
};

type FormState = {
  title: string;
  brief: string;
  storyCount: string;
  model: string;
};

const FIELD_ORDER = ["title", "storyCount", "model", "brief"] as const;
type FieldKey = (typeof FIELD_ORDER)[number];

function wrapText(value: string, width: number, maxLines: number): string[] {
  const safeWidth = Math.max(12, width);
  const source = value.length > 0 ? value : " ";
  const logicalLines = source.split(/\r?\n/);
  const output: string[] = [];
  for (const logicalLine of logicalLines) {
    if (output.length >= maxLines) break;
    const words = logicalLine.split(/\s+/).filter(Boolean);
    if (words.length === 0) {
      output.push(pad(" ", safeWidth));
      continue;
    }
    let line = "";
    for (const word of words) {
      const candidate = line ? `${line} ${word}` : word;
      if (candidate.length > safeWidth) {
        output.push(pad(truncate(line || word, safeWidth), safeWidth));
        line = line ? word : "";
        if (output.length >= maxLines) break;
      } else {
        line = candidate;
      }
    }
    if (output.length >= maxLines) break;
    if (line) {
      output.push(pad(truncate(line, safeWidth), safeWidth));
    }
  }
  return output.slice(0, maxLines);
}

function fieldLabel(key: FieldKey): string {
  switch (key) {
    case "title":
      return "Title";
    case "storyCount":
      return "Story count";
    case "model":
      return "Model (optional)";
    case "brief":
      return "Brief";
  }
}

function renderEditor(form: FormState, activeField: FieldKey, width: number, statusLine: string, busy: boolean): string[] {
  const totalWidth = Math.max(92, width);
  const leftWidth = Math.max(34, Math.floor(totalWidth * 0.38));
  const rightWidth = Math.max(52, totalWidth - leftWidth - 3);

  const leftLines: string[] = [pad("[NEW SPEC]", leftWidth)];
  for (const field of FIELD_ORDER) {
    const marker = field === activeField ? "> " : "  ";
    const value = form[field] || (field === "model" ? "auto" : "");
    leftLines.push(pad(truncate(`${marker}${fieldLabel(field)}`, leftWidth), leftWidth));
    const preview = field === "brief"
      ? value.replace(/\s+/g, " ").trim() || "Describe the feature you want Rorca to spec..."
      : value || (field === "storyCount" ? "8" : field === "title" ? "Short human-readable title" : "optional model override");
    leftLines.push(pad(truncate(`   ${preview}`, leftWidth), leftWidth));
  }

  const rightLines: string[] = [pad(`[${fieldLabel(activeField).toUpperCase()}]`, rightWidth)];
  const currentValue = form[activeField] || (activeField === "storyCount" ? "8" : "");
  if (activeField === "brief") {
    rightLines.push(...wrapText(currentValue || "Paste or type a spec brief here. Enter inserts a new line.", rightWidth, 16));
  } else {
    rightLines.push(...wrapText(currentValue || " ", rightWidth, 4));
  }
  rightLines.push(" ".repeat(rightWidth));
  rightLines.push(...wrapText(
    "Tab/Shift+Tab move fields • Enter adds line in brief or jumps forward • Backspace deletes • Ctrl+S submits • Esc closes",
    rightWidth,
    6,
  ));

  const height = Math.max(leftLines.length, rightLines.length);
  while (leftLines.length < height) leftLines.push(" ".repeat(leftWidth));
  while (rightLines.length < height) rightLines.push(" ".repeat(rightWidth));

  const lines: string[] = [truncate(busy ? `${statusLine} (working)` : statusLine, totalWidth)];
  for (let i = 0; i < height; i += 1) {
    lines.push(`${leftLines[i]} │ ${rightLines[i]}`);
  }
  lines.push(" ");
  lines.push(truncate("Suggested flow: title → story count → model → brief → Ctrl+S submit", totalWidth));
  return lines;
}

function nextField(field: FieldKey): FieldKey {
  const index = FIELD_ORDER.indexOf(field);
  return FIELD_ORDER[Math.min(FIELD_ORDER.length - 1, index + 1)]!;
}

function previousField(field: FieldKey): FieldKey {
  const index = FIELD_ORDER.indexOf(field);
  return FIELD_ORDER[Math.max(0, index - 1)]!;
}

function extractGeneratedSpecId(payload: GenerateSpecResponse | GenerateJobResponse): string | null {
  if (payload.spec?.id) {
    return payload.spec.id;
  }
  if ("id" in payload && typeof payload.id === "string") {
    return payload.id;
  }
  return payload.slug ?? null;
}

export async function openSpecAuthor(
  ctx: ExtensionCommandContext,
  _pi: ExtensionAPI,
  workspaceId: string,
  baseUrl: string,
  token?: string,
): Promise<void> {
  if (!ctx.ui.custom) {
    notify(ctx.ui, "Pi custom UI is unavailable in this session. Use /rorca-tui as fallback.", "warning");
    return;
  }

  let generatedSpecId: string | null = null;

  await ctx.ui.custom<void>((tui, _theme, _keybindings, done) => {
    let mounted = true;
    let busy = false;
    let activeField: FieldKey = "title";
    let statusLine = `Create a new spec for ${workspaceId}`;
    const form: FormState = {
      title: "",
      brief: "",
      storyCount: "8",
      model: "",
    };

    const requestRender = () => {
      if (mounted) tui.requestRender();
    };

    const submit = async () => {
      const title = form.title.trim();
      const brief = form.brief.trim();
      const storyCount = Number.parseInt(form.storyCount.trim() || "8", 10);
      const model = form.model.trim();

      if (!title) {
        statusLine = "Title is required.";
        notify(ctx.ui, statusLine, "warning");
        requestRender();
        return;
      }
      if (!brief) {
        statusLine = "Brief is required.";
        notify(ctx.ui, statusLine, "warning");
        requestRender();
        return;
      }
      if (!Number.isFinite(storyCount) || storyCount < 1 || storyCount > 500) {
        statusLine = "Story count must be between 1 and 500.";
        notify(ctx.ui, statusLine, "warning");
        requestRender();
        return;
      }

      busy = true;
      statusLine = `Generating spec \"${title}\"…`;
      requestRender();

      try {
        const body: GenerateSpecRequest = {
          workspaceId,
          title,
          brief,
          storyCount,
          ...(model ? { model } : {}),
        };
        const created = await apiFetchJson<GenerateSpecResponse>(baseUrl, "/api/specs/generate", {
          method: "POST",
          body,
          token,
        });

        generatedSpecId = extractGeneratedSpecId(created);
        if (!generatedSpecId && created.jobId) {
          statusLine = `Generation queued (${created.jobId}). Waiting…`;
          requestRender();
          for (;;) {
            await new Promise((resolve) => setTimeout(resolve, 2000));
            const job = await apiFetchJson<GenerateJobResponse>(baseUrl, `/api/specs/generate/job/${encodeURIComponent(created.jobId)}`, { token });
            const progress = typeof job.progress === "number" ? `${job.progress}%` : job.status || "pending";
            statusLine = `Generation job ${created.jobId}: ${progress}`;
            requestRender();
            if (job.status === "done") {
              generatedSpecId = extractGeneratedSpecId(job);
              break;
            }
            if (job.status === "failed") {
              throw new Error(job.error || "Spec generation job failed");
            }
          }
        }

        if (!generatedSpecId) {
          throw new Error("Spec generated but no spec id was returned");
        }

        statusLine = `Generated spec ${generatedSpecId}`;
        notify(ctx.ui, `Generated spec ${generatedSpecId}`, "success");
        mounted = false;
        done();
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        statusLine = `Spec generation failed: ${message}`;
        notify(ctx.ui, statusLine, "error");
      } finally {
        busy = false;
        requestRender();
      }
    };

    const appendText = (value: string) => {
      form[activeField] += value;
      requestRender();
    };

    const deleteChar = () => {
      form[activeField] = form[activeField].slice(0, -1);
      requestRender();
    };

    return {
      render: (width) => renderEditor(form, activeField, width, statusLine, busy),
      handleInput: (data) => {
        if (busy) {
          return;
        }
        const key = normalizeKey(data);
        if (data === "\u0013") {
          void submit();
          return;
        }
        if (data === "\u007f" || data === "\b") {
          deleteChar();
          return;
        }
        if (key === "q" || key === "escape" || key === "ctrl+c") {
          mounted = false;
          done();
          return;
        }
        if (key === "tab" || key === "down" || key === "right") {
          activeField = nextField(activeField);
          requestRender();
          return;
        }
        if (key === "shift+tab" || key === "up" || key === "left") {
          activeField = previousField(activeField);
          requestRender();
          return;
        }
        if (key === "enter") {
          if (activeField === "brief") {
            appendText("\n");
          } else {
            activeField = nextField(activeField);
            requestRender();
          }
          return;
        }
        if (data.length === 1 && data >= " " && data !== "\u007f") {
          appendText(data);
        }
      },
      invalidate: () => {
        mounted = false;
      },
    };
  }, { overlay: true });

  if (generatedSpecId) {
    try {
      await openSpecDetail(ctx, _pi, generatedSpecId, baseUrl, token, workspaceId);
    } catch (error) {
      notify(ctx.ui, `Generated ${generatedSpecId}, but opening the spec failed: ${error instanceof Error ? error.message : String(error)}`, "warning");
    }
  }
}

import { spawnSync } from "node:child_process";
import { openRunView } from "./tui/run-view.js";
import { openSpecBoard } from "./tui/spec-board.js";
import { openSpecDetail } from "./tui/spec-detail.js";
import { openSpecAuthor } from "./tui/spec-author.js";
import { openMemoryBrowser } from "./tui/memory-browser.js";
import { openDirectionView } from "./tui/direction-view.js";
import { openWorkspaceView } from "./tui/workspace-view.js";
import {
  type ExtensionAPI,
  type ExtensionCommandContext,
  apiFetchJson,
  getBaseUrl,
  notify,
  readDefaultToken,
  resolveWorkspace,
} from "./tui/shared.js";

type PipelineRunListItem = {
  id: number;
  status: string;
  spec_path?: string;
  started_at?: string;
};

type PipelineRunListResponse = {
  items?: PipelineRunListItem[];
};

type SpecListItem = {
  id: string;
  title?: string;
  specName?: string;
  generatedAt?: string;
  createdAt?: string;
  created_at?: string;
};

type SpecListResponse = {
  items?: SpecListItem[];
};

function shellQuote(value: string): string {
  return `'${value.replace(/'/g, `'\\''`)}'`;
}

function escapeAppleScript(value: string): string {
  return value.replace(/\\/g, "\\\\").replace(/"/g, '\\"');
}

function extractSpecSlug(specPath: string | undefined): string {
  const fileName = specPath?.split("/").pop() ?? "";
  return fileName.endsWith(".json") ? fileName.slice(0, -5) : fileName;
}

function sortRunCandidates(items: PipelineRunListItem[]): PipelineRunListItem[] {
  const priority = new Map<string, number>([
    ["running", 0],
    ["paused", 1],
    ["queued", 2],
    ["cancelling", 3],
    ["failed", 4],
    ["partial_failure", 5],
    ["done", 6],
    ["passed", 7],
    ["cancelled", 8],
  ]);

  return [...items].sort((left, right) => {
    const leftPriority = priority.get(left.status) ?? 99;
    const rightPriority = priority.get(right.status) ?? 99;
    if (leftPriority !== rightPriority) {
      return leftPriority - rightPriority;
    }
    return right.id - left.id;
  });
}

export default function rorcaPiExtension(pi: ExtensionAPI) {
  const baseUrl = getBaseUrl();
  const token = readDefaultToken();
  let activeWorkspaceId = process.env.RORCA_WORKSPACE_ID?.trim() || "";

  const ensureWorkspace = async (ctx?: ExtensionCommandContext) => {
    if (activeWorkspaceId) {
      return activeWorkspaceId;
    }
    const workspace = await resolveWorkspace(baseUrl, token, activeWorkspaceId || undefined, ctx?.cwd);
    activeWorkspaceId = workspace.id;
    process.env.RORCA_WORKSPACE_ID = workspace.id;
    process.env.RORCA_WORKSPACE_NAME = workspace.label;
    process.env.RORCA_WORKSPACE_PATH = workspace.path;
    return activeWorkspaceId;
  };

  const withWorkspace = (handler: (workspaceId: string, ctx: ExtensionCommandContext, args?: string) => Promise<void>) => {
    return async (args: string | undefined, ctx: ExtensionCommandContext) => {
      try {
        const workspaceId = await ensureWorkspace(ctx);
        await handler(workspaceId, ctx, args);
      } catch (error) {
        notify(ctx.ui, error instanceof Error ? error.message : String(error), "error");
      }
    };
  };

  const resolveRunId = async (workspaceId: string, args?: string): Promise<number> => {
    const requested = args?.trim();
    if (requested && /^\d+$/.test(requested)) {
      return Number(requested);
    }

    const runs = await apiFetchJson<PipelineRunListResponse>(
      baseUrl,
      `/api/pipeline/runs?workspaceId=${encodeURIComponent(workspaceId)}&limit=100`,
      { token },
    );
    const items = runs.items ?? [];

    if (items.length === 0) {
      throw new Error("No pipeline runs exist for the active workspace yet.");
    }

    if (requested) {
      const matched = items.find((item) => extractSpecSlug(item.spec_path) === requested);
      if (!matched) {
        throw new Error(`No pipeline run found for spec ${requested}.`);
      }
      return matched.id;
    }

    return sortRunCandidates(items)[0]!.id;
  };

  const resolveSpecId = async (workspaceId: string, args?: string): Promise<string> => {
    const requested = args?.trim();
    if (requested) {
      return requested;
    }

    const specs = await apiFetchJson<SpecListResponse>(
      baseUrl,
      `/api/specs?workspaceId=${encodeURIComponent(workspaceId)}&limit=100`,
      { token },
    );
    const items = specs.items ?? [];

    if (items.length === 0) {
      throw new Error("No specs exist for the active workspace yet.");
    }

    const newestFirst = [...items].sort((left, right) => {
      const leftTime = Date.parse(left.generatedAt ?? left.createdAt ?? left.created_at ?? "");
      const rightTime = Date.parse(right.generatedAt ?? right.createdAt ?? right.created_at ?? "");
      if (Number.isFinite(leftTime) && Number.isFinite(rightTime) && leftTime !== rightTime) {
        return rightTime - leftTime;
      }
      if (Number.isFinite(leftTime) !== Number.isFinite(rightTime)) {
        return Number.isFinite(rightTime) ? 1 : -1;
      }
      return left.id.localeCompare(right.id);
    });

    return newestFirst[0]!.id;
  };

  pi.registerCommand("rorca:board", {
    description: "Open the Rorca Pi-native spec board",
    handler: withWorkspace(async (_workspaceId, ctx) => {
      await openSpecBoard(ctx, pi, baseUrl, token);
    }),
  });

  pi.registerCommand("rorca:run", {
    description: "Open the Pi-native Rorca run cockpit. Args: run id, spec slug, or nothing for the latest active run.",
    handler: withWorkspace(async (workspaceId, ctx, args) => {
      const runId = await resolveRunId(workspaceId, args);
      await openRunView(ctx, pi, runId, baseUrl, token);
    }),
  });

  pi.registerCommand("rorca:spec", {
    description: "Open the Pi-native Rorca spec detail view. Args: spec id, or nothing for the newest spec.",
    handler: withWorkspace(async (workspaceId, ctx, args) => {
      const specId = await resolveSpecId(workspaceId, args);
      await openSpecDetail(ctx, pi, specId, baseUrl, token, workspaceId);
    }),
  });

  pi.registerCommand("rorca:new-spec", {
    description: "Open the Pi-native Rorca spec authoring flow.",
    handler: withWorkspace(async (workspaceId, ctx) => {
      await openSpecAuthor(ctx, pi, workspaceId, baseUrl, token);
    }),
  });

  pi.registerCommand("rorca:forge", {
    description: "Alias for /rorca:new-spec — create a new spec inside Pi.",
    handler: withWorkspace(async (workspaceId, ctx) => {
      await openSpecAuthor(ctx, pi, workspaceId, baseUrl, token);
    }),
  });

  pi.registerCommand("rorca:memory", {
    description: "Open the Rorca memory browser",
    handler: withWorkspace(async (workspaceId, ctx) => {
      await openMemoryBrowser(ctx, pi, workspaceId, baseUrl, token);
    }),
  });

  pi.registerCommand("rorca:direction", {
    description: "Open the Rorca direction stack view",
    handler: withWorkspace(async (workspaceId, ctx) => {
      await openDirectionView(ctx, pi, workspaceId, baseUrl, token);
    }),
  });

  pi.registerCommand("rorca:workspace", {
    description: "Open the Rorca workspace switcher",
    handler: withWorkspace(async (workspaceId, ctx) => {
      await openWorkspaceView(ctx, pi, workspaceId, (nextWorkspace) => {
        activeWorkspaceId = nextWorkspace.id;
        process.env.RORCA_WORKSPACE_ID = nextWorkspace.id;
        process.env.RORCA_WORKSPACE_NAME = nextWorkspace.label;
        process.env.RORCA_WORKSPACE_PATH = nextWorkspace.path;
      }, baseUrl, token);
    }),
  });

  pi.registerCommand("rorca-tui", {
    description: "Open the Rorca TUI in Terminal.app",
    handler: async (_args, ctx) => {
      const cwd = ctx.cwd || process.cwd();
      const shellCommand = `cd ${shellQuote(cwd)} && clear && rorca tui`;
      const result = spawnSync(
        "osascript",
        [
          "-e",
          'tell application "Terminal"',
          "-e",
          "activate",
          "-e",
          `do script \"${escapeAppleScript(shellCommand)}\"`,
          "-e",
          "end tell",
        ],
        { env: process.env },
      );

      if (result.status !== 0) {
        const stderr = result.stderr?.toString("utf8").trim();
        throw new Error(stderr || "Failed to launch Terminal.app for rorca tui");
      }

      notify(ctx.ui, "Opened Rorca TUI in Terminal.app", "success");
    },
  });

  pi.on?.("session_start", async (_event, ctx) => {
    try {
      const workspace = await resolveWorkspace(baseUrl, token, activeWorkspaceId || undefined, ctx.cwd);
      activeWorkspaceId = workspace.id;
      process.env.RORCA_WORKSPACE_ID = workspace.id;
      process.env.RORCA_WORKSPACE_NAME = workspace.label;
      process.env.RORCA_WORKSPACE_PATH = workspace.path;

      notify(ctx.ui, `Rorca extension ready for ${workspace.label}`, "success");

      void Promise.allSettled([
        fetch(`${baseUrl}/api/recall?workspaceId=${encodeURIComponent(workspace.id)}&titlesOnly=true`, {
          headers: token ? { Authorization: `Bearer ${token}` } : undefined,
        }),
        fetch(`${baseUrl}/api/workspaces/${encodeURIComponent(workspace.id)}/health`, {
          headers: token ? { Authorization: `Bearer ${token}` } : undefined,
        }),
      ]);
    } catch (error) {
      notify(ctx.ui, `Rorca extension degraded: ${error instanceof Error ? error.message : String(error)}`, "warning");
    }
  });

  pi.on?.("agent_end", async () => {
    // no-op
  });

  pi.on?.("session_shutdown", async () => {
    // no-op
  });
}

import { openRunView } from "./run-view.js";
import {
  type ExtensionAPI,
  type ExtensionCommandContext,
  apiFetchJson,
  normalizeKey,
  notify,
  timeAgo,
  truncate,
} from "./shared.js";

type SpecStory = {
  id?: string;
  title?: string;
  story?: string;
  description?: string;
  status?: string;
  completed?: boolean;
  excluded?: boolean;
  passes?: boolean;
  complexity?: number;
  priority?: number;
  timeoutMinutes?: number;
  dependsOn?: string[];
  dependencies?: string[];
  acceptanceCriteria?: string[];
  acceptance_criteria?: string[];
  tasks?: string[];
};

type SpecDetailPayload = {
  id?: string;
  specName?: string;
  title?: string;
  brief?: string;
  model?: string | null;
  createdAt?: string;
  created_at?: string;
  _status?: string;
  readinessPercent?: number;
  tags?: string[];
  userStories?: SpecStory[];
  stories?: SpecStory[];
};

type PipelineRunListItem = {
  id: number;
  status?: string;
  spec_path?: string;
};

type PipelineRunListResponse = {
  items?: PipelineRunListItem[];
};

const MAX_VISIBLE_STORIES = 9;
const MAX_VISIBLE_DETAIL_LINES = 18;

function storyTitle(story: SpecStory, index: number): string {
  return story.title || story.story || story.description || `Story ${index + 1}`;
}

function storyCriteria(story: SpecStory): string[] {
  const criteria = story.acceptanceCriteria ?? story.acceptance_criteria ?? [];
  return Array.isArray(criteria) ? criteria.map(String) : [];
}

function storyTasks(story: SpecStory): string[] {
  return Array.isArray(story.tasks) ? story.tasks.map(String) : [];
}

function storyDependencies(story: SpecStory): string[] {
  const dependencies = story.dependsOn ?? story.dependencies ?? [];
  return Array.isArray(dependencies) ? dependencies.map(String) : [];
}

function specStories(spec: SpecDetailPayload): SpecStory[] {
  return spec.userStories ?? spec.stories ?? [];
}

function storyStatus(story: SpecStory): string {
  if (story.status) {
    return story.status;
  }
  return story.completed ? "done" : "pending";
}

function extractSpecSlug(specPath: string | undefined): string {
  const fileName = specPath?.split("/").pop() ?? "";
  return fileName.endsWith(".json") ? fileName.slice(0, -5) : fileName;
}

function sortRunCandidates(items: PipelineRunListItem[]): PipelineRunListItem[] {
  const priority = new Map<string, number>([
    ["running", 0],
    ["paused", 1],
    ["queued", 2],
    ["cancelling", 3],
    ["failed", 4],
    ["partial_failure", 5],
    ["done", 6],
    ["passed", 7],
    ["cancelled", 8],
  ]);

  return [...items].sort((left, right) => {
    const leftPriority = priority.get(left.status || "") ?? 99;
    const rightPriority = priority.get(right.status || "") ?? 99;
    if (leftPriority !== rightPriority) {
      return leftPriority - rightPriority;
    }
    return right.id - left.id;
  });
}

function renderWrapped(text: string, width: number): string[] {
  const safeWidth = Math.max(20, width);
  const words = text.split(/\s+/).filter(Boolean);
  if (words.length === 0) {
    return [""];
  }

  const lines: string[] = [];
  let current = "";
  for (const word of words) {
    const next = current ? `${current} ${word}` : word;
    if (next.length > safeWidth && current) {
      lines.push(current);
      current = word;
    } else {
      current = next;
    }
  }
  if (current) {
    lines.push(current);
  }
  return lines;
}

function visibleStoryWindow(stories: SpecStory[], selectedIndex: number): { start: number; end: number } {
  if (stories.length <= MAX_VISIBLE_STORIES) {
    return { start: 0, end: stories.length };
  }

  const halfWindow = Math.floor(MAX_VISIBLE_STORIES / 2);
  const start = Math.max(0, Math.min(selectedIndex - halfWindow, stories.length - MAX_VISIBLE_STORIES));
  return { start, end: start + MAX_VISIBLE_STORIES };
}

export async function openSpecDetail(
  ctx: ExtensionCommandContext,
  _pi: ExtensionAPI,
  specId: string,
  baseUrl: string,
  token?: string,
  workspaceId?: string,
): Promise<void> {
  if (!ctx.ui.custom) {
    notify(ctx.ui, `Pi custom UI is unavailable for spec ${specId}. Use /rorca-tui as fallback.`, "warning");
    return;
  }

  let openRunId: number | null = null;

  await ctx.ui.custom<void>((tui, _theme, _keybindings, done) => {
    let spec: SpecDetailPayload | null = null;
    let latestRun: PipelineRunListItem | null = null;
    let selectedIndex = 0;
    let scrollOffset = 0;
    let busy = true;
    let mounted = true;
    let refreshTimer: NodeJS.Timeout | undefined;
    let statusLine = `Loading spec ${specId}…`;

    const requestRender = () => {
      if (mounted) {
        tui.requestRender();
      }
    };

    const refresh = async () => {
      if (!workspaceId) {
        throw new Error("No workspace selected for spec detail");
      }
      const [nextSpec, runPayload] = await Promise.all([
        apiFetchJson<SpecDetailPayload>(
          baseUrl,
          `/api/specs/${encodeURIComponent(specId)}?workspaceId=${encodeURIComponent(workspaceId)}`,
          { token },
        ),
        apiFetchJson<PipelineRunListResponse>(
          baseUrl,
          `/api/pipeline/runs?workspaceId=${encodeURIComponent(workspaceId)}&limit=100`,
          { token },
        ),
      ]);
      spec = nextSpec;
      latestRun = sortRunCandidates((runPayload.items ?? []).filter((item) => extractSpecSlug(item.spec_path) === specId))[0] ?? null;
      const stories = specStories(spec);
      selectedIndex = Math.max(0, Math.min(selectedIndex, Math.max(0, stories.length - 1)));
      statusLine = `${spec.title || spec.specName || specId} • ${stories.length} stories • ${spec._status || "unknown"}`;
    };

    const runAction = (action: () => Promise<void>) => {
      if (busy) {
        return;
      }
      busy = true;
      statusLine = "Working…";
      requestRender();

      void (async () => {
        try {
          await action();
          await refresh();
        } catch (error) {
          const message = error instanceof Error ? error.message : String(error);
          statusLine = `Error: ${message}`;
          notify(ctx.ui, message, "error");
        } finally {
          busy = false;
          requestRender();
        }
      })();
    };

    const startRefreshTimer = () => {
      if (refreshTimer) {
        clearInterval(refreshTimer);
      }
      refreshTimer = setInterval(() => {
        void refresh().then(requestRender).catch((error) => {
          const message = error instanceof Error ? error.message : String(error);
          statusLine = `Refresh failed: ${message}`;
          requestRender();
        });
      }, 30_000);
    };

    void (async () => {
      try {
        await refresh();
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        statusLine = `Failed to load spec: ${message}`;
        notify(ctx.ui, message, "error");
      } finally {
        busy = false;
        startRefreshTimer();
        requestRender();
      }
    })();

    return {
      handleInput(data: string) {
        const key = normalizeKey(data);
        const stories = spec ? specStories(spec) : [];

        if (key === "q" || key === "escape" || key === "ctrl+c") {
          mounted = false;
          if (refreshTimer) {
            clearInterval(refreshTimer);
          }
          done();
          return;
        }

        if (busy) {
          return;
        }

        if (key === "down" || key === "j") {
          const nextIndex = Math.min(selectedIndex + 1, Math.max(0, stories.length - 1));
          if (nextIndex !== selectedIndex) {
            selectedIndex = nextIndex;
            scrollOffset = 0;
          }
          requestRender();
          return;
        }

        if (key === "up" || key === "k") {
          const nextIndex = Math.max(0, selectedIndex - 1);
          if (nextIndex !== selectedIndex) {
            selectedIndex = nextIndex;
            scrollOffset = 0;
          }
          requestRender();
          return;
        }

        if (key === "home") {
          selectedIndex = 0;
          scrollOffset = 0;
          requestRender();
          return;
        }

        if (key === "end") {
          selectedIndex = Math.max(0, stories.length - 1);
          scrollOffset = 0;
          requestRender();
          return;
        }

        if (key === "pagedown") {
          const nextIndex = Math.min(selectedIndex + 5, Math.max(0, stories.length - 1));
          if (nextIndex !== selectedIndex) {
            selectedIndex = nextIndex;
            scrollOffset = 0;
          }
          requestRender();
          return;
        }

        if (key === "pageup") {
          const nextIndex = Math.max(0, selectedIndex - 5);
          if (nextIndex !== selectedIndex) {
            selectedIndex = nextIndex;
            scrollOffset = 0;
          }
          requestRender();
          return;
        }

        if (key === "[") {
          scrollOffset = Math.max(0, scrollOffset - 1);
          requestRender();
          return;
        }

        if (key === "]") {
          scrollOffset += 1;
          requestRender();
          return;
        }

        if (key === "r") {
          runAction(async () => {
            await refresh();
            statusLine = `Refreshed ${spec?.title || spec?.specName || specId}`;
          });
          return;
        }

        if (key === "a") {
          runAction(async () => {
            await apiFetchJson(baseUrl, `/api/specs/${encodeURIComponent(specId)}/approve`, {
              method: "POST",
              token,
              body: { workspaceId },
            });
            statusLine = `Approved ${spec?.title || spec?.specName || specId}`;
            notify(ctx.ui, `Approved ${spec?.title || spec?.specName || specId}`, "success");
          });
          return;
        }

        if (key === "x") {
          runAction(async () => {
            const ok = (await ctx.ui.confirm?.("Reject spec", `Reject ${spec?.title || spec?.specName || specId}?`)) ?? false;
            if (!ok) {
              statusLine = `Reject cancelled for ${spec?.title || spec?.specName || specId}`;
              return;
            }
            await apiFetchJson(baseUrl, `/api/specs/${encodeURIComponent(specId)}/reject`, {
              method: "POST",
              token,
              body: { workspaceId, reason: "Rejected from Pi detail" },
            });
            statusLine = `Rejected ${spec?.title || spec?.specName || specId}`;
            notify(ctx.ui, `Rejected ${spec?.title || spec?.specName || specId}`, "warning");
          });
          return;
        }

        if (key === "s") {
          runAction(async () => {
            const payload = await apiFetchJson<{ queued?: boolean; runId?: number; queuePosition?: number }>(
              baseUrl,
              `/api/pipeline/queue`,
              {
                method: "POST",
                token,
                body: { workspaceId, specId },
              },
            );
            if (payload.queued) {
              statusLine = `Queued run for ${spec?.title || spec?.specName || specId} at position ${payload.queuePosition ?? "?"}`;
              notify(ctx.ui, statusLine, "info");
            } else {
              statusLine = `Started run ${payload.runId ?? ""} for ${spec?.title || spec?.specName || specId}`.trim();
              notify(ctx.ui, statusLine, "success");
              if (payload.runId) {
                openRunId = payload.runId;
                mounted = false;
                if (refreshTimer) {
                  clearInterval(refreshTimer);
                }
                done();
              }
            }
          });
          return;
        }

        if (key === "o") {
          if (!latestRun?.id) {
            statusLine = `No pipeline run found yet for ${spec?.title || spec?.specName || specId}`;
            requestRender();
            return;
          }
          openRunId = latestRun.id;
          mounted = false;
          if (refreshTimer) {
            clearInterval(refreshTimer);
          }
          done();
        }
      },

      render(width: number): string[] {
        const lines: string[] = [];
        const safeWidth = Math.max(60, width);
        const leftWidth = Math.max(24, Math.floor(safeWidth * 0.34));
        const rightWidth = Math.max(28, safeWidth - leftWidth - 3);

        lines.push(`Rorca Spec Detail — ${spec?.title || spec?.specName || specId}`);
        lines.push("");

        if (!spec) {
          lines.push(truncate(statusLine, safeWidth));
          lines.push(truncate("q quit", safeWidth));
          return lines;
        }

        const stories = specStories(spec);
        const selectedStory = stories[selectedIndex];
        const criteria = selectedStory ? storyCriteria(selectedStory) : [];
        const tasks = selectedStory ? storyTasks(selectedStory) : [];
        const dependencies = selectedStory ? storyDependencies(selectedStory) : [];
        const summaryLines = [
          `Status: ${spec._status || "unknown"}`,
          `Readiness: ${spec.readinessPercent ?? 0}%`,
          `Stories: ${stories.length}`,
          `Model: ${spec.model || "auto"}`,
          `Created: ${timeAgo(spec.createdAt ?? spec.created_at)}`,
          `Run: ${latestRun ? `#${latestRun.id} ${latestRun.status || "unknown"}` : "none"}`,
          `Tags: ${(spec.tags ?? []).join(", ") || "none"}`,
        ];
        const storyWindow = visibleStoryWindow(stories, selectedIndex);
        const storyList = stories.length
          ? [
              ...(storyWindow.start > 0 ? [truncate(`… ${storyWindow.start} earlier stories`, leftWidth)] : []),
              ...stories.slice(storyWindow.start, storyWindow.end).map((story, visibleIndex) => {
                const index = storyWindow.start + visibleIndex;
                const marker = index === selectedIndex ? ">" : " ";
                const storyId = story.id ? `${story.id} · ` : "";
                const excluded = story.excluded ? " · excluded" : "";
                return truncate(`${marker} ${storyId}${storyTitle(story, index)} [${storyStatus(story)}${excluded}]`, leftWidth);
              }),
              ...(storyWindow.end < stories.length ? [truncate(`… ${stories.length - storyWindow.end} more stories`, leftWidth)] : []),
            ]
          : ["No stories in this spec."];

        const detailLines: string[] = [];
        detailLines.push("Brief:");
        detailLines.push(...renderWrapped(spec.brief || "No brief", Math.max(20, rightWidth - 2)).map((line) => `  ${truncate(line, rightWidth - 2)}`));
        detailLines.push("");
        if (selectedStory) {
          detailLines.push(`Story ${selectedIndex + 1}: ${truncate(storyTitle(selectedStory, selectedIndex), rightWidth - 9)}`);
          detailLines.push(`ID: ${selectedStory.id || `story-${selectedIndex + 1}`}`);
          detailLines.push(`Status: ${storyStatus(selectedStory)}${selectedStory.excluded ? " · excluded" : ""}${selectedStory.passes === true ? " · passes" : ""}`);
          detailLines.push(`Depends on: ${dependencies.join(", ") || "none"}`);
          detailLines.push(`Complexity: ${selectedStory.complexity ?? "n/a"} • Priority: ${selectedStory.priority ?? "n/a"} • Timeout: ${selectedStory.timeoutMinutes ?? "default"}m`);
          const narrative = selectedStory.story || selectedStory.description;
          if (narrative) {
            detailLines.push("Narrative:");
            detailLines.push(...renderWrapped(narrative, rightWidth).map((line) => `  ${truncate(line, rightWidth - 2)}`));
          }
          detailLines.push("Acceptance:");
          if (criteria.length === 0) {
            detailLines.push("  No acceptance criteria");
          } else {
            for (const item of criteria) {
              detailLines.push(...renderWrapped(`• ${item}`, rightWidth).map((line) => truncate(line, rightWidth)));
            }
          }
          detailLines.push("");
          detailLines.push("Tasks:");
          if (tasks.length === 0) {
            detailLines.push("  No implementation tasks");
          } else {
            for (const task of tasks) {
              detailLines.push(...renderWrapped(`• ${task}`, rightWidth).map((line) => truncate(line, rightWidth)));
            }
          }
        } else {
          detailLines.push("Select a story to inspect.");
        }

        const leftPaneLines = [...summaryLines, "", "Stories:", ...storyList];
        const paneHeight = Math.max(leftPaneLines.length, Math.min(MAX_VISIBLE_DETAIL_LINES, Math.max(8, detailLines.length)));
        const maxScrollOffset = Math.max(0, detailLines.length - paneHeight);
        const clampedOffset = Math.max(0, Math.min(scrollOffset, maxScrollOffset));
        if (clampedOffset !== scrollOffset) {
          scrollOffset = clampedOffset;
        }
        const visibleDetails = detailLines.slice(scrollOffset, scrollOffset + paneHeight);

        for (let row = 0; row < paneHeight; row += 1) {
          const left = leftPaneLines[row] || "";
          const right = visibleDetails[row] || "";
          lines.push(`${truncate(left, leftWidth).padEnd(leftWidth)} │ ${truncate(right, rightWidth)}`);
        }

        lines.push("");
        if (maxScrollOffset > 0) {
          lines.push(truncate(`Detail scroll ${scrollOffset + 1}-${Math.min(detailLines.length, scrollOffset + paneHeight)} of ${detailLines.length}`, safeWidth));
        }
        lines.push(truncate(statusLine, safeWidth));
        lines.push(truncate("j/k move stories • Home/End jump • PgUp/PgDn step • s start run and open if immediate • o open latest run • a approve • x reject • r refresh • [/] scroll detail • q quit", safeWidth));
        return lines;
      },

      invalidate() {
        // Stateless renderer
      },
    };
  });

  if (openRunId != null) {
    await openRunView(ctx, _pi, openRunId, baseUrl, token);
  }
}

import { existsSync, readFileSync, renameSync, writeFileSync } from "node:fs";
import os from "node:os";
import path from "node:path";

export type NotifyLevel = "info" | "warning" | "error" | "success";

export type UiApi = {
  notify?: (message: string, level?: NotifyLevel) => void;
  setStatus?: (id: string, status: string | undefined) => void;
  setWidget?: (id: string, widget: unknown) => void;
  confirm?: (title: string, message: string) => Promise<boolean>;
  custom?: <T>(
    factory: (
      tui: { requestRender: (full?: boolean) => void; stop: () => void; start: () => void },
      theme: unknown,
      keybindings: unknown,
      done: (result: T) => void,
    ) => {
      render: (width: number) => string[];
      handleInput?: (data: string) => void;
      invalidate?: () => void;
    },
    options?: { overlay?: boolean; overlayOptions?: unknown; onHandle?: (handle: unknown) => void },
  ) => Promise<T>;
};

export type ExtensionCommandContext = {
  ui: UiApi;
  hasUI?: boolean;
  cwd?: string;
};

export type ExtensionAPI = {
  registerCommand: (
    name: string,
    options: {
      description: string;
      handler: (args: string | undefined, ctx: ExtensionCommandContext) => Promise<void> | void;
    },
  ) => void;
  on?: (
    eventName: string,
    handler: (event: unknown, ctx: ExtensionCommandContext) => Promise<void> | void,
  ) => void;
};

export type WorkspaceSummary = {
  id: string;
  label: string;
  path: string;
  domains?: string[];
};

export type ApiError = Error & { status?: number; body?: string };

export function getBaseUrl(): string {
  return (process.env.RORCA_BASE_URL?.trim() || "http://localhost:3030").replace(/\/$/, "");
}

export function readDefaultToken(): string | undefined {
  const tokenPath = path.join(os.homedir(), ".rorca", "mcp-token");
  if (!existsSync(tokenPath)) {
    return undefined;
  }

  try {
    const token = readFileSync(tokenPath, "utf8").trim();
    return token || undefined;
  } catch {
    return undefined;
  }
}

export function notify(ui: UiApi | undefined, message: string, level: NotifyLevel = "info"): void {
  if (typeof ui?.notify === "function") {
    ui.notify(message, level);
    return;
  }

  const prefix = level === "error" ? "[rorca:error]" : level === "warning" ? "[rorca:warn]" : "[rorca]";
  const text = `${prefix} ${message}`;
  if (level === "error") {
    console.error(text);
  } else if (level === "warning") {
    console.warn(text);
  } else {
    console.log(text);
  }
}

export function buildHeaders(token?: string, extra?: Record<string, string>): Record<string, string> {
  const headers: Record<string, string> = {
    Accept: "application/json",
    ...extra,
  };
  if (token) {
    headers.Authorization = `Bearer ${token}`;
  }
  return headers;
}

export async function apiFetchJson<T>(
  baseUrl: string,
  pathname: string,
  options: { method?: string; body?: unknown; token?: string } = {},
): Promise<T> {
  const response = await fetch(`${baseUrl}${pathname}`, {
    method: options.method ?? (options.body == null ? "GET" : "POST"),
    headers: buildHeaders(options.token, options.body == null ? undefined : { "Content-Type": "application/json" }),
    body: options.body == null ? undefined : JSON.stringify(options.body),
  });

  if (!response.ok) {
    const body = await response.text().catch(() => "");
    const error = new Error(`HTTP ${response.status} ${response.statusText} for ${pathname}`) as ApiError;
    error.status = response.status;
    error.body = body;
    throw error;
  }

  return (await response.json()) as T;
}

export async function apiFetchText(
  baseUrl: string,
  pathname: string,
  options: { method?: string; body?: unknown; token?: string } = {},
): Promise<string> {
  const response = await fetch(`${baseUrl}${pathname}`, {
    method: options.method ?? (options.body == null ? "GET" : "POST"),
    headers: buildHeaders(options.token, options.body == null ? undefined : { "Content-Type": "application/json" }),
    body: options.body == null ? undefined : JSON.stringify(options.body),
  });

  if (!response.ok) {
    const body = await response.text().catch(() => "");
    const error = new Error(`HTTP ${response.status} ${response.statusText} for ${pathname}`) as ApiError;
    error.status = response.status;
    error.body = body;
    throw error;
  }

  return response.text();
}

export async function getWorkspaces(baseUrl: string, token?: string): Promise<WorkspaceSummary[]> {
  const payload = await apiFetchJson<{ items?: WorkspaceSummary[] }>(baseUrl, "/api/workspaces", { token });
  return payload.items ?? [];
}

export async function resolveWorkspace(
  baseUrl: string,
  token?: string,
  preferredWorkspaceId?: string,
  cwdHint?: string,
): Promise<WorkspaceSummary> {
  const envId = preferredWorkspaceId || process.env.RORCA_WORKSPACE_ID?.trim();
  const workspaces = await getWorkspaces(baseUrl, token);
  if (workspaces.length === 0) {
    throw new Error("No workspaces registered in Rorca");
  }

  if (envId) {
    const match = workspaces.find((workspace) => workspace.id === envId);
    if (match) {
      return match;
    }
  }

  const candidateCwds = [cwdHint?.trim(), process.cwd()].filter((value): value is string => Boolean(value));
  for (const cwd of candidateCwds) {
    const cwdMatch = workspaces.find((workspace) => cwd === workspace.path || cwd.startsWith(`${workspace.path}${path.sep}`));
    if (cwdMatch) {
      return cwdMatch;
    }
  }

  return workspaces[0]!;
}

export function truncate(value: string, max: number): string {
  if (max <= 0) {
    return "";
  }
  return value.length <= max ? value : `${value.slice(0, Math.max(0, max - 3))}...`;
}

export function leftTruncate(value: string, max: number): string {
  if (max <= 0) {
    return "";
  }
  return value.length <= max ? value : `...${value.slice(-(max - 3))}`;
}

export function pad(value: string, width: number): string {
  if (width <= 0) {
    return "";
  }
  if (value.length >= width) {
    return value.slice(0, width);
  }
  return value + " ".repeat(width - value.length);
}

export function timeAgo(iso: string | null | undefined): string {
  if (!iso) {
    return "unknown";
  }

  const elapsedMs = Date.now() - new Date(iso).getTime();
  if (!Number.isFinite(elapsedMs)) {
    return "unknown";
  }
  if (elapsedMs < 60_000) {
    return "<1m";
  }
  const minutes = Math.floor(elapsedMs / 60_000);
  if (minutes < 60) {
    return `${minutes}m ago`;
  }
  const hours = Math.floor(minutes / 60);
  if (hours < 24) {
    return `${hours}h ago`;
  }
  const days = Math.floor(hours / 24);
  return `${days}d ago`;
}

export function normalizeKey(chunk: string): string {
  switch (chunk) {
    case "\u0003":
      return "ctrl+c";
    case "\r":
    case "\n":
      return "enter";
    case "\u001b":
      return "escape";
    case "\u001b[A":
      return "up";
    case "\u001b[B":
      return "down";
    case "\u001b[C":
      return "right";
    case "\u001b[D":
      return "left";
    case "\u001b[5~":
      return "pageup";
    case "\u001b[6~":
      return "pagedown";
    case "\u001b[H":
    case "\u001bOH":
      return "home";
    case "\u001b[F":
    case "\u001bOF":
      return "end";
    case "\t":
      return "tab";
    case "\u001b[Z":
      return "shift+tab";
    default:
      return chunk;
  }
}

export function readJsonFile<T>(filePath: string, fallback: T): T {
  if (!existsSync(filePath)) {
    return fallback;
  }
  try {
    return JSON.parse(readFileSync(filePath, "utf8")) as T;
  } catch {
    return fallback;
  }
}

export function writeJsonAtomic(filePath: string, value: unknown): void {
  const tmpFilePath = `${filePath}.tmp`;
  writeFileSync(tmpFilePath, JSON.stringify(value, null, 2), "utf8");
  renameSync(tmpFilePath, filePath);
}

export function decodeOutputLines(payload: unknown): string[] {
  if (!payload || typeof payload !== "object") {
    return [];
  }
  const output = (payload as { output?: unknown }).output;
  return Array.isArray(output) ? output.map((line) => String(line)) : [];
}

